def solve(p, n):
    g = [[0]*n for _ in range(n)]
    for r in range(0, p+1):
        if 0 <= p-r < n: g[r][p-r] = 2
        if 0 <= p+r < n: g[r][p+r] = 2
    for r in range(n):
        for c in range(n):
            d = c - r
            if d < p and d % 4 == p % 4 and r >= (p - d)//2 + 1:
                g[r][c] = 1
    return g

